"""Read fixtures generated by main f3760fe, not by the candidate writer."""

from __future__ import annotations

import base64
import hashlib
import importlib
import json
import sqlite3
from pathlib import Path

FIXTURE_PATH = Path(__file__).parent / "vectors/main_f3760fe_compat.json"
FIXTURE = json.loads(FIXTURE_PATH.read_text(encoding="utf-8"))
MASTER = bytes.fromhex(FIXTURE["master_key_hex"])


def test_original_package_and_default_ciphertext_remain_readable():
    floorvault = importlib.import_module("floorvault")
    ciphertext = base64.b64decode(FIXTURE["ciphertext_base64"])
    with floorvault.FloorVault(MASTER) as crypto:
        assert (
            crypto.decrypt(ciphertext, table="credentials", record_id="u1", column="token")
            == "baseline-secret"
        )
        assert crypto.encrypt(
            "new", table="credentials", record_id="u1", column="token"
        ).startswith(b"FLV2")


def test_existing_recovery_bundle_and_beacon_key_keep_their_identity():
    floorvault = importlib.import_module("floorvault")
    key = floorvault.recover_master_key(
        base64.b64decode(FIXTURE["recovery_bundle_base64"]),
        bytes.fromhex(FIXTURE["recovery_key_hex"]),
    )
    try:
        assert key.get_bytes() == MASTER
    finally:
        key.wipe()
    beacons = importlib.import_module("floorvault.beacons")
    assert beacons.derive_beacon_key(MASTER).hex() == FIXTURE["beacon_key_hex"]


def test_default_vault_opens_existing_sealed_store_and_retirement(tmp_path, monkeypatch):
    floorvault = importlib.import_module("floorvault")
    for name in ("HERMES_VAULT_KEY", "VAULT_MASTER_KEY", "APPSTATE_KEY"):
        monkeypatch.delenv(name, raising=False)
    monkeypatch.setenv("FLOOR_VAULT_KEY", MASTER.hex())
    with sqlite3.connect(tmp_path / "vault.db") as db:
        db.executescript(FIXTURE["vault_sql"])
    store = floorvault.VaultStore(tmp_path, seal_listing_metadata=True)
    assert store.resolve_secret("vault_baseline") == {"value": "baseline-token"}
    assert store.get_meta("vault_baseline").label == "Baseline item"
    assert store.retired_modern_id("legacy-baseline") == "vault_baseline"


def test_original_custody_defaults_do_not_follow_hermes_home(tmp_path, monkeypatch):
    floorvault = importlib.import_module("floorvault")
    monkeypatch.setenv("HERMES_HOME", str(tmp_path / "hermes"))
    provider = floorvault.AdaptiveKeyProvider()
    assert provider.service_name == "floorvault"
    assert provider.fallback_dir == Path.home() / ".floorvault"
    assert provider.allow_legacy_env_vars is False
    linux = importlib.import_module("floorvault.providers.linux_keyring")
    transit = importlib.import_module("floorvault.providers.vault_transit")
    assert linux._ATTRIBUTE_KEY == "floorvault"
    assert transit.PURPOSE == "floorvault-master-wrap"


def test_original_main_fixture_is_pinned_public_test_data():
    assert (
        hashlib.sha256(FIXTURE_PATH.read_bytes()).hexdigest()
        == "9b207962b1dda21a86de082f224a7304b2ca7d26d53080c23c95644b1db876c1"
    )
    assert FIXTURE["master_key_hex"] == bytes(range(32)).hex()
    assert FIXTURE["recovery_key_hex"] == bytes(range(32, 64)).hex()
